{
  "distSpecVersion": "1.1.1",
  "storage": {
    "rootDirectory": "/tmp/zot",
    "gc": true,
    "dedupe": false,
    "retention": {
      "dryRun": false,
      "delay": "24h",
      "policies": [
        {
          "repositories": ["**"],
          "deleteReferrers": true,
          "keepTags": [
            {
              "mostRecentlyPushedCount": 5
            }
          ]
        }
      ]
    },
    "storageDriver": {
      "name": "s3",
      "region": "us-east-1",
      "bucket": "zot",
      "regionendpoint": "http://garage.storage.svc.cluster.local:3900",
      "secure": false,
      "skipverify": true
    }
  },
  "http": {
    "address": "0.0.0.0",
    "port": "5000",
    "readTimeout": "300s",
    "writeTimeout": "300s",
    "externalUrl": "https://registry.jnobrega.com",
    "auth": {
      "htpasswd": {
        "path": "/secret/htpasswd"
      },
      "openid": {
        "providers": {
          "oidc": {
            "credentialsFile": "/oidc/oidc-credentials.json",
            "name": "Authentik SSO",
            "issuer": "https://auth.jnobrega.com/application/o/Zot/",
            "keypath": "",
            "scopes": ["openid", "profile", "email", "groups"]
          }
        }
      }
    }
  },
  "log": {
    "level": "info"
  },
  "extensions": {
    "ui": { "enable": true },
    "search": { "enable": true },
    "scrub": { "enable": true, "interval": "24h" }
  }
}
